const NUM = 17 /* colored stripes */ , MAR = 40;

function setup() {
	S=max(windowWidth, windowHeight);
	S = (~~(S/NUM)-5) * NUM
	createCanvas(windowWidth, windowHeight); // (S + MAR, S + MAR);
	frameRate(30);

	noStroke();
	fill(0);
}

function draw() {
	blendMode(BLEND)
	background("white");
	// blendMode(DIFFERENCE)

	const t = frameCount/60;

	// fill("rgba(255,192,203,0.5)");
	// drawCircleNew(width*0.5 - S/3, height/2, S, [0.85, 0.15])
	drawCircleNew(width*0.5 + sin(t) * S/3, height/2, S, [0.85, 0.15])

	// fill("rgba(255,20,147,0.5)");
	// drawCircleNew(width*0.5 + S/3, height/2, S, [0.15, 0.85])
	drawCircleNew(width*0.5 - cos(t) * S/3, height/2, S, [0.15, 0.85])
}

function drawCircleNew(x, y, dia, RAT) { // RATIO [0.8, 0.2] start end fraction b&w per stripe, must be 1 in sum (0.8+0.2)
	const NM = NUM-1 + RAT[1]; // NUM = 11 -> 10.2 -> 10 b/w changes plus one last black 
	const TH = dia / NM;
	push()
	// blendMode(BLEND)
	beginClip();
	let yy = y - dia/2;
	for (let i = 0; i < NUM; i++, yy += TH) {
		const f = i/(NUM-1); // 0..1
		const H = TH * map(f, 0, 1, RAT[0], RAT[1]); 
		rect(x-dia/2, yy, dia, H);
	}
	endClip();
	// blendMode(DIFFERENCE); // not working, why?
	circle(x, y, dia);
	pop();
}

